head.script:
scwin.screenId = "jlddst00800";

///////// 1. 변수 및 선언 영역 /////////

scwin.loadYn = false;


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init = function () {
    /* sdd-asis-lifecycle:begin init — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("method", "callPapagoTranslator");
    scwin.swapOptions('#language', '#targetLanguage');
    scwin.swapOptions('#targetLanguage', '#language');
    (($c.util.getComponent('slc_target')) && ($c.util.getComponent('slc_target')).setDisabled ? ($c.util.getComponent('slc_target')).setDisabled((true) === 'disabled' || (true) === 'readonly' || (true) === 'checked' ? true : (true)) : void 0);
    (($c.util.getComponent('slc_source')) && ($c.util.getComponent('slc_source')).setDisabled ? ($c.util.getComponent('slc_source')).setDisabled((true) === 'disabled' || (true) === 'readonly' || (true) === 'checked' ? true : (true)) : void 0);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.init();
        $("#txa_text").on("propertychange change keyup paste input focus", function() {
                if (!scwin.loadYn) {
                    $c.util.getComponent('txa_text').setValue("");
                    scwin.loadYn = true;
                }
        });
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst00800.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jlddst00800.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.searchForm_onsubmit
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.searchForm_onsubmit = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin searchForm_onsubmit — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        return false;
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst00800.searchForm_onsubmit' }); }
};

/**
 * @event
 * @name scwin.img_32_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.img_32_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin img_32_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.fnSearch()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst00800.img_32_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_fnSearch_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_fnSearch_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_fnSearch_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.fnSearch(); return false;
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst00800.btn_fnSearch_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fnSearch_ajaxsubmit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fnSearch_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSearch_ajaxsubmit",
        method: "post",
        action: "/common/krxPapagoTranslator.do",
        ref: "dma_fnSearchAjaxsubmitReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jlddst00800.tx_fnSearch_ajaxsubmit" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.fnSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearch = async function () {
    /* sdd-asis-lifecycle:begin fnSearch — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (await scwin.checkLength()) {
        (($c.util.getComponent('slc_target')) && ($c.util.getComponent('slc_target')).setDisabled ? ($c.util.getComponent('slc_target')).setDisabled((false) === 'disabled' || (false) === 'readonly' || (false) === 'checked' ? true : (false)) : void 0);
        (($c.util.getComponent('slc_source')) && ($c.util.getComponent('slc_source')).setDisabled ? ($c.util.getComponent('slc_source')).setDisabled((false) === 'disabled' || (false) === 'readonly' || (false) === 'checked' ? true : (false)) : void 0);
        $c.util.getComponent('slc_target').setValue("en");
        $c.util.getComponent('slc_source').setValue("ko");
        scwin.dial();
        await scwin.tx_fnSearch_ajaxsubmit();
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchCallBack
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.fnSearchCallBack = async function (data) {
    /* sdd-asis-lifecycle:begin fnSearchCallBack — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    (($c.util.getComponent('slc_target')) && ($c.util.getComponent('slc_target')).setDisabled ? ($c.util.getComponent('slc_target')).setDisabled((true) === 'disabled' || (true) === 'readonly' || (true) === 'checked' ? true : (true)) : void 0);
    (($c.util.getComponent('slc_source')) && ($c.util.getComponent('slc_source')).setDisabled ? ($c.util.getComponent('slc_source')).setDisabled((true) === 'disabled' || (true) === 'readonly' || (true) === 'checked' ? true : (true)) : void 0);
    try {
        if (scwin.isHTML(data)) {
            await $c.win.alert("현재 해당 서비스를 이용할 수 없습니다. 시스템 관리자에게 문의 바랍니다.");
            document.write(data);
            document.close();
        } else {
            const resultJson = (typeof data === "string" ? JSON.parse(data) : data);
            const transrationText = resultJson.dataList[0].response.translatedText;
            $c.util.getComponent('txa_afterText').setValue(transrationText);
        }
    } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'jlddst00800' });
        await $c.win.alert("지금 사용하고 계신 단어로는 사이트 이용이 불가능합니다.");
        $c.win.setPageFrameSrc($c.win.getFrame(), null);
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.dial
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.dial = function () {
    /* sdd-asis-lifecycle:begin dial — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    ($.fn && $.fn.dialog ? $("#dialogLoading").dialog({ title: 'Translation is in progress.', height: 100, closeOnEscape: false, draggable: false, resizable: false, modal: true }) : undefined);
    $("#dialogLoading").attr("title", "Translation is in progress.");
    console.error("[sdd] 미실현 동작: set_visible (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_visible — {target}.setStyle({args}) */
    $(".ui-widget-overlay").css("background-image", "none");
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.isHTML
 * @author Inswave
 * @date 2026. 09. 29
 * @param str
 * @returns
 * @hidden N
*/
scwin.isHTML = function (str) {
    /* sdd-asis-lifecycle:begin isHTML — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const pattern = /<([A-Za-z][A-Za-z0-9]*)\b[^>]*>(.*?)<\/\1>/;
    return pattern.test(str);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.swapOptions
 * @author Inswave
 * @date 2026. 09. 29
 * @param selector1 selector2
 * @returns
 * @hidden N
*/
scwin.swapOptions = function (selector1, selector2) {
    /* sdd-asis-lifecycle:begin swapOptions — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $(selector1).change(function() {
            const selectedOption = $(selector1).val() === 'ko' ? 'en' : 'ko';
            $(selector2).val(selectedOption);
    });
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.swapValues
 * @author Inswave
 * @date 2026. 09. 29
 * @param id1 id2
 * @returns
 * @hidden N
*/
scwin.swapValues = function (id1, id2) {
    /* sdd-asis-lifecycle:begin swapValues — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const temp = $(id1).val();
    $(id1).val($(id2).val());
    $(id2).val(temp);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.btnSwapValues
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.btnSwapValues = function () {
    /* sdd-asis-lifecycle:begin btnSwapValues — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.swapValues('#source', '#target');
    scwin.swapValues('#text', '#afterText');
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.changeSwapComboBox
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.changeSwapComboBox = function () {
    /* sdd-asis-lifecycle:begin changeSwapComboBox — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $('select').change(function() {
            const otherSelectBox = $(this).attr('id') === 'source' ? '#target' : '#source';
            if ($(this).val() === $(otherSelectBox).val()) {
                $(otherSelectBox).val($(this).val() === 'ko' ? 'en' : 'ko');
            }
    });
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkLength
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.checkLength = async function () {
    /* sdd-asis-lifecycle:begin checkLength — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const limit = 4500;
    const textValue = $c.util.getComponent('txa_text').getValue();
    const trimmedValue = textValue.trim();
    const length = trimmedValue.length;
    if (length === 0) {
        await $c.win.alert("번역할 문자를 넣어주세요.");
        return false;
    } else {
        if (length > limit) {
            await $c.win.alert("입력 가능한 글자는 " + limit + "자를 넘을 수 없습니다.");
            return false;
        }
    }
    return true;
    /* sdd-asis-lifecycle:end */
};
